#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <errno.h>
#include <inttypes.h>

static long long ll_abs(long long x)
{
    return x < 0 ? -x : x;
}

static long long gcd_ll(long long a, long long b)
{
    while (b != 0) {
        long long r = a % b;
        a = b;
        b = r;
    }
    return a;
}

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    char *endptr1, *endptr2;
    errno = 0;
    long long v1 = strtoll(argv[1], &endptr1, 10);
    long long v2 = strtoll(argv[2], &endptr2, 10);
    if (endptr1 == argv[1] || *endptr1 != '\0' || endptr2 == argv[2] || *endptr2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (v1 == LLONG_MIN || v2 == LLONG_MIN) {
        puts("OVERFLOW");
        return 0;
    }
    long long a = ll_abs(v1);
    long long b = ll_abs(v2);
    if (a > 1000000LL || b > 1000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (a == 0 && b == 0) {
        puts("gcd=0 lcm=0");
        return 0;
    }
    long long g = gcd_ll(a, b);
    long long l = (a / g) * b;
    printf("gcd=%lld lcm=%lld\n", g, l);
    return 0;
}
